// The following is not legal
  const // This is MyConst integer c_myConst := 1;
  // A block comment should have been used instead
  const /* This is MyConst */ integer c_myConst := 1;
  // A line comment like this works as well
  const // This is MyConst 
     integer c_myConst := 1;

// The following is not legal
  const // This is MyConst integer c_myConst := 1;
  // A block comment should have been used instead
  const /* This is MyConst */ integer c_myConst := 1;
  // A line comment like this works as well
  const // This is MyConst 
     integer c_myConst := 1;
